interface LanguageRange {
  readonly range: string;
  readonly weight: number;
}

type LocalizedStringWarningType =
  | "INCOMPLETE_CARDINALITY_TRANSLATIONS"
  | "INCOMPLETE_ORDINALITY_TRANSLATIONS";

interface LocalizedStringWarning {
  readonly type: LocalizedStringWarningType;
  readonly source: string;
  readonly locale: LocaleTag;
  readonly key: string;
  readonly placeholder: string;
  readonly missingLanguageForms: readonly (
    CardinalityFormName | OrdinalityFormName
  )[];
  readonly message: string;
}

interface OrdinalData {
  readonly $lokalized: "ordinal-data";
  readonly provenance: DataProvenance;
}

interface CardinalRangeData {
  readonly $lokalized: "cardinal-range-data";
  readonly provenance: DataProvenance;
}

interface CatalogIdentity {
  readonly catalogVersion: string;
  readonly catalogFingerprint: string;
}

type StringsLoadCoverage =
  | {
      readonly kind: "lookup";
      // Normalized planning input; it need not occur in the manifest.
      readonly lookupLocale: LocaleTag;
    }
  | { readonly kind: "entire-manifest" };

interface StringsLoadVerification {
  readonly source: "verified-manifest-v1";
  readonly producerImplementation: "lokalized-js";
  readonly producerVersion: string;
  readonly manifestLocaleConfiguration: LocaleConfiguration;
  readonly catalogIdentity: CatalogIdentity;
  readonly cldrVersion: string;
  readonly dataFingerprint: string;
  readonly ianaRegistryDate: string;
  readonly ianaDataFingerprint: string;
  readonly behavioralVectorsVersion: string;
  readonly localeDataMode: "pinned";
  readonly cardinalityMode: "exact";
  readonly coverage: StringsLoadCoverage;
  // Renderer-kernel plan order and exact loaded tags, respectively.
  readonly plannedLocales: readonly LocaleTag[];
  readonly coveredLocales: readonly LocaleTag[];
  readonly complete: boolean;
}

interface LocaleConfiguration {
  readonly fallbackLocale: LocaleTag;
  readonly supportedLocales: readonly LocaleTag[];
  readonly tiebreakers: Readonly<Record<string, readonly LocaleTag[]>>;
}

type Placeholders =
  | Readonly<Record<string, unknown>>
  | ReadonlyMap<string, unknown>;

interface ParsedStringsFile {
  readonly $lokalized: "parsed-strings-file";
  readonly locale: LocaleTag;
  readonly sources: readonly string[];
  readonly strings: readonly LocalizedStringInput[];
  readonly originsByKey: Readonly<Record<string, readonly string[]>>;
  readonly warnings: readonly LocalizedStringWarning[];
}

type CatalogInput =
  | string
  | Uint8Array
  | ParsedStringsFile
  | readonly LocalizedStringInput[];

type CatalogMap =
  | Readonly<Record<LocaleTag, CatalogInput>>
  | ReadonlyMap<LocaleTag, CatalogInput>;

type TiebreakerMap =
  | Readonly<Record<string, readonly LocaleTag[]>>
  | ReadonlyMap<string, readonly LocaleTag[]>;

interface CreateStringsBehaviorOptions {
  readonly pluralData?: {
    readonly ordinal?: OrdinalData;
    readonly ranges?: CardinalRangeData;
  };

  readonly phoneticResolver?: PhoneticResolver;
  readonly onFailure?: FailureHandler;
  readonly fallbackPolicy?: BuiltinFallbackPolicy | FallbackPolicy;
  readonly bidiIsolation?: BidiIsolation;
  readonly onWarning?: (warning: LocalizedStringWarning) => void;
  readonly onFallback?: FallbackObserver;

  // No customization in v1. A non-undefined value is rejected.
  readonly runtimeLimits?: undefined;
}

type LocaleSourceOptions =
  | {
      readonly locale: LocaleTag;
      readonly localeResolver?: never;
      readonly localeMatchResolver?: never;
    }
  | {
      readonly locale?: never;
      readonly localeResolver: () => LocaleTag;
      readonly localeMatchResolver?: never;
    }
  | {
      readonly locale?: never;
      readonly localeResolver?: never;
      readonly localeMatchResolver: () => LocaleMatchResult;
    };

type CommonCreateStringsOptions =
  CreateStringsBehaviorOptions & LocaleSourceOptions;

type DirectCreateStringsOptions = CommonCreateStringsOptions & {
  readonly fallbackLocale: LocaleTag;
  readonly strings: CatalogMap;
  readonly tiebreakers?: TiebreakerMap;
  readonly catalogIdentity?: CatalogIdentity;
  readonly loadingLimits?: Partial<StringsLoadingLimits>;
  readonly loaded?: never;
};

type LoadedCreateStringsOptions = CommonCreateStringsOptions & {
  readonly loaded: LoadedStrings;
  readonly fallbackLocale?: never;
  readonly strings?: never;
  readonly tiebreakers?: never;
  readonly catalogIdentity?: never;
  readonly loadingLimits?: never;
};

type CreateStringsOptions =
  | DirectCreateStringsOptions
  | LoadedCreateStringsOptions;

~~~ts
interface TranslationBehaviorOptions {
  readonly bidiIsolation?: BidiIsolation;
  readonly onFailure?: FailureHandler;
  readonly fallbackPolicy?: BuiltinFallbackPolicy | FallbackPolicy;
  readonly onFallback?: FallbackObserver;
}

type TranslationOptions = TranslationBehaviorOptions & (
  | { readonly locale?: LocaleTag; readonly localeMatch?: never }
  | { readonly locale?: never; readonly localeMatch: LocaleMatchResult }
);

function forLocale(locale: LocaleTag): Readonly<TranslationOptions>;
function forLocaleMatch(
  localeMatch: LocaleMatchResult
): Readonly<TranslationOptions>;

interface DirectLocaleContext {
  readonly lookupLocale: LocaleTag;
  readonly localeMatch: LocaleMatchResult;
}

interface Strings {
  readonly get: (
    key: string,
    placeholders?: Placeholders,
    options?: TranslationOptions
  ) => string;

  readonly t: Strings["get"];

  readonly getResult: (
    key: string,
    placeholders?: Placeholders,
    options?: TranslationOptions
  ) => TranslationResult;

  readonly getDirectLocaleContext: (
    locale: LocaleTag
  ) => DirectLocaleContext;

  readonly getSupportedLocales: () => readonly LocaleTag[];
  readonly getKeysForLocale: (locale: LocaleTag) => readonly string[];
  readonly getMissingKeys: (
    sourceLocale: LocaleTag,
    targetLocale: LocaleTag
  ) => readonly string[];
  readonly getLocaleConfiguration: () => LocaleConfiguration;
  readonly getCatalogIdentity: () => CatalogIdentity | null;
  readonly isCatalogComplete: () => boolean;
  readonly getLoadVerification: () => StringsLoadVerification | null;
  readonly getWarnings: () => readonly LocalizedStringWarning[];
}

~~~ts
type LocaleMatchType =
  | "none"
  | "exact"
  | "canonical"
  | "extended-range"
  | "wildcard"
  | "cldr-fallback"
  | "likely-subtag"
  | "primary-language";

interface LocaleMatchResult {
  readonly requestedLanguageRanges: readonly LanguageRange[];
  readonly locale: LocaleTag | null;
  readonly languageRange: LanguageRange | null;
  readonly effectiveWeight: number | null;
  readonly matchType: LocaleMatchType;
  readonly fallbackLocale: LocaleTag;
  readonly consideredLocales: readonly LocaleTag[];
  readonly isMatch: boolean;
}

interface TranslationResultBase {
  readonly key: string;
  readonly translation: string;
  readonly lookupLocale: LocaleTag;
  readonly localeMatch: LocaleMatchResult;
  readonly attemptedLocales: readonly LocaleTag[];
  readonly isFallback: boolean;
  readonly status: TranslationStatus;
}

interface TranslatedResult extends TranslationResultBase {
  readonly status: "translated";
  readonly resolvedLocale: LocaleTag;
  readonly failureReason: null;
  readonly cause: null;
}

interface FailureResult extends TranslationResultBase {
  readonly status: "returned-key" | "returned-string";
  readonly resolvedLocale: null;
  readonly failureReason: FailureReason;
  readonly cause: unknown | null; // non-null iff resolution-failure
}

type TranslationResult = TranslatedResult | FailureResult;

The full, size-heavy language-range solver is exported by `lokalized/negotiate`; it is browser/edge
safe but intentionally absent from the root graph:

~~~ts
interface LocaleMatcher {
  readonly matchFor: (locale: LocaleTag) => LocaleMatchResult;
  readonly bestMatchFor: (locale: LocaleTag) => LocaleTag;
}

interface LocaleNegotiator extends LocaleMatcher {
  readonly matchForLanguageRanges: (
    ranges: readonly LanguageRange[]
  ) => LocaleMatchResult;
  readonly bestMatchForLanguageRanges: (
    ranges: readonly LanguageRange[]
  ) => LocaleTag;
  readonly bestMatchForAcceptLanguage: (
    value: string | null | undefined
  ) => LocaleTag;
}

function parseLanguageRanges(value: string): readonly LanguageRange[];
function createLocaleNegotiator(
  configuration: LocaleConfiguration
): LocaleNegotiator;
function forLanguageRanges(
  negotiator: LocaleNegotiator,
  ranges: readonly LanguageRange[]
): Readonly<TranslationOptions>;
function forAcceptLanguage(
  negotiator: LocaleNegotiator,
  value: string | null | undefined
): Readonly<TranslationOptions>;

const ianaRegistryDate: string;
const ianaDataFingerprint: string;
~~~

The root graph instead exports a pure small chooser and a browser convenience:

~~~ts
function chooseLocaleForPreferredLanguages(
  configuration: LocaleConfiguration,
  languages: readonly string[]
): LocaleTag;
function chooseBrowserLocale(configuration: LocaleConfiguration): LocaleTag;
~~~

~~~ts
interface ReturnKeyResponse {
  readonly action: "return-key";
}
interface ReturnStringResponse {
  readonly action: "return-string";
  readonly translation: string;
}
interface ThrowResponse {
  readonly action: "throw";
}
type FailureResponse =
  | ReturnKeyResponse
  | ReturnStringResponse
  | ThrowResponse;

const RETURN_KEY: Readonly<ReturnKeyResponse>;
const THROW_EXCEPTION: Readonly<ThrowResponse>;
function returnString(translation: string): Readonly<ReturnStringResponse>;

interface TranslationFailure {
  readonly key: string;
  readonly lookupLocale: LocaleTag;
  readonly localeMatch: LocaleMatchResult;
  readonly attemptedLocales: readonly LocaleTag[];
  // Frozen, enumerable, null-prototype record; it has no inherited magic keys.
  readonly placeholders: Readonly<Record<string, unknown>>;
  readonly reason: FailureReason;
  readonly cause: unknown | null;
  readonly message: string; // redacted; excludes placeholder values and cause message
}

type FailureHandler = (failure: TranslationFailure) => FailureResponse;
interface FallbackEvent {
  readonly key: string;
  readonly lookupLocale: LocaleTag;
  readonly localeMatch: LocaleMatchResult;
  readonly attemptedLocales: readonly LocaleTag[];
  readonly resolvedLocale: LocaleTag;
  readonly precedingFailures: readonly Readonly<{
    locale: LocaleTag;
    reason: FailureReason;
    cause: unknown | null;
  }>[];
}
type FallbackObserver = (event: FallbackEvent) => void;
type PhoneticResolver = (
  term: string,
  locale: LocaleTag
) => PhoneticValue;

Exported library errors have the following declaration contract:

~~~ts
interface LokalizedError extends Error {
  readonly code: LokalizedErrorCode;
  readonly cause?: unknown;
}

interface MissingTranslationError extends LokalizedError {
  readonly code: "MISSING_TRANSLATION";
  readonly failure: TranslationFailure;
}

interface UnsupportedLocaleError extends LokalizedError {
  readonly code: "UNSUPPORTED_LOCALE";
  readonly locale: LocaleTag;
}

interface ExpressionEvaluationError extends LokalizedError {
  readonly code: "EXPRESSION_EVALUATION";
}

interface ResolutionError extends LokalizedError {
  readonly code:
    | "RESOLUTION_INVALID_ARGUMENT"
    | "RESOLUTION_INVALID_STATE";
  readonly thrownValue?: "null" | "undefined";
}

interface StringsParseError extends LokalizedError {
  readonly code: "STRINGS_PARSE";
  readonly source: string;
  readonly line: number | null;
  readonly column: number | null;
  readonly path: string | null;
}

interface StringsLoadingError extends LokalizedError {
  readonly code: "STRINGS_LOADING";
  readonly failures: readonly LoadFailure[];
}

interface DigestUnavailableError extends LokalizedError {
  readonly code: "DIGEST_UNAVAILABLE";
}

interface ConfigurationError extends LokalizedError {
  readonly code: "CONFIGURATION";
}

interface CatchOnlyErrorClass<T extends LokalizedError> {
  readonly prototype: T;
  [Symbol.hasInstance](value: unknown): value is T;
  // Deliberately no call or construct signature.
}

const LokalizedError: CatchOnlyErrorClass<LokalizedError>;
const MissingTranslationError: CatchOnlyErrorClass<MissingTranslationError>;
const UnsupportedLocaleError: CatchOnlyErrorClass<UnsupportedLocaleError>;
const ExpressionEvaluationError: CatchOnlyErrorClass<ExpressionEvaluationError>;
const ResolutionError: CatchOnlyErrorClass<ResolutionError>;
const StringsParseError: CatchOnlyErrorClass<StringsParseError>;
const StringsLoadingError: CatchOnlyErrorClass<StringsLoadingError>;
const DigestUnavailableError: CatchOnlyErrorClass<DigestUnavailableError>;
const ConfigurationError: CatchOnlyErrorClass<ConfigurationError>;

~~~ts
interface LocalizedStringNodeInput {
  readonly translation?: string;
  readonly commentary?: string;
  readonly placeholders?:
    | Readonly<Record<string, PlaceholderDefinition>>
    | ReadonlyMap<string, PlaceholderDefinition>;
  readonly alternatives?: readonly WholeMessageAlternativeInput[];
}

interface LocalizedStringInput extends LocalizedStringNodeInput {
  readonly key: string;
}

interface WholeMessageAlternativeInput extends LocalizedStringNodeInput {
  readonly expression: string;
}

type PlaceholderDefinition =
  | LanguageFormTranslationInput
  | ExpressionTranslationInput;

interface LanguageFormTranslationInput {
  readonly kind: "language-form";
  readonly value?: string;
  readonly range?: { readonly start: string; readonly end: string };
  readonly translations: Readonly<Partial<Record<LanguageFormName, string>>>;
}

interface ExpressionTranslationInput {
  readonly kind: "expression";
  readonly translation: string;
  readonly alternatives?: readonly {
    readonly expression: string;
    readonly translation: string;
  }[];
}

function defineLocalizedString(
  input: LocalizedStringInput
): Readonly<LocalizedStringInput>;

function defineCatalog(
  inputs: readonly LocalizedStringInput[]
): readonly Readonly<LocalizedStringInput>[];

~~~ts
interface DecimalValue {
  readonly $lokalized: "decimal";
  readonly value: string;
}

interface PluralOperandValue {
  readonly $lokalized: "plural-operands";
  readonly value: string;
  readonly visibleDecimalPlaces?: number;
  readonly compactExponent?: number;
}

function decimal(value: string): DecimalValue;
function pluralOperands(
  value: string,
  options?: {
    readonly visibleDecimalPlaces?: number;
    readonly compactExponent?: number;
  }
): PluralOperandValue;
~~~

interface TaggedLanguageFormValue<
  Axis extends LanguageFormAxis,
  Name extends LanguageFormName
> {
  readonly $lokalized: "language-form";
  readonly axis: Axis;
  readonly name: Name;
  readonly renderName: string;
}

type LanguageFormValue =
  | TaggedLanguageFormValue<"cardinality", CardinalityFormName>
  | TaggedLanguageFormValue<"ordinality", OrdinalityFormName>
  | TaggedLanguageFormValue<"gender", GenderFormName>
  | TaggedLanguageFormValue<"grammatical-case", GrammaticalCaseFormName>
  | TaggedLanguageFormValue<"definiteness", DefinitenessFormName>
  | TaggedLanguageFormValue<"classifier", ClassifierFormName>
  | TaggedLanguageFormValue<"formality", FormalityFormName>
  | TaggedLanguageFormValue<"clusivity", ClusivityFormName>
  | TaggedLanguageFormValue<"animacy", AnimacyFormName>
  | TaggedLanguageFormValue<"phonetic", PhoneticFormName>;

type CardinalityValue =
  TaggedLanguageFormValue<"cardinality", CardinalityFormName>;
type OrdinalityValue =
  TaggedLanguageFormValue<"ordinality", OrdinalityFormName>;
type PhoneticValue = TaggedLanguageFormValue<"phonetic", PhoneticFormName>;

type PluralNumber = number | bigint | DecimalValue;

// Root exports; strict cardinal data is in the root graph.
function cardinalityForNumber(
  value: PluralNumber,
  locale: LocaleTag
): CardinalityValue;
function cardinalityForOperands(
  value: PluralOperandValue,
  locale: LocaleTag
): CardinalityValue;
function supportedCardinalitiesForLocale(
  locale: LocaleTag
): readonly CardinalityValue[];
function getSupportedCardinalityLocaleTags(): readonly LocaleTag[];

// `lokalized/data/ordinal` exports.
const ordinalData: OrdinalData;
function ordinalityForNumber(
  value: PluralNumber,
  locale: LocaleTag
): OrdinalityValue;
function ordinalityForOperands(
  value: PluralOperandValue,
  locale: LocaleTag
): OrdinalityValue;
function supportedOrdinalitiesForLocale(
  locale: LocaleTag
): readonly OrdinalityValue[];
function getSupportedOrdinalityLocaleTags(): readonly LocaleTag[];

// `lokalized/data/ranges` exports.
const cardinalRangeData: CardinalRangeData;
function cardinalityForRange(
  start: CardinalityValue,
  end: CardinalityValue,
  locale: LocaleTag
): CardinalityValue;

// Example exported constant:
const GENDER_FEMININE:
  TaggedLanguageFormValue<"gender", "GENDER_FEMININE">;

`parseStrings` is synchronous:

~~~ts
interface StringsLoadingLimits {
  readonly maximumInputBytes: number;
  readonly maximumReaderCharacters: number;
  readonly maximumJsonNestingDepth: number;
  readonly maximumTotalInputBytes: number;
  readonly maximumLocalizedStringsFiles: number;
  readonly maximumTranslationNodes: number;
  readonly maximumWarnings: number;
}

type ParsedCatalogLimits = Pick<
  StringsLoadingLimits,
  | "maximumLocalizedStringsFiles"
  | "maximumTranslationNodes"
  | "maximumWarnings"
>;

interface ParseStringsOptions {
  readonly locale: LocaleTag;
  readonly source?: string;
  readonly limits?: Partial<StringsLoadingLimits>;
  readonly onWarning?: (warning: LocalizedStringWarning) => void;
}

function parseStrings(
  input: string | Uint8Array,
  options: ParseStringsOptions
): ParsedStringsFile;

function mergeParsedStringsFiles(
  files: readonly ParsedStringsFile[],
  options?: { readonly limits?: Partial<ParsedCatalogLimits> }
): ParsedStringsFile;
~~~

- the language-neutral `requirements.json` and evidence schemas live beside those vectors; each
  implementation may add implementation-required evidence records without reclassifying portable
  requirements;

The behavioral format uses stable semantic IDs:

~~~json
{
  "formatVersion": 1,
  "behavioralVectorsVersion": "1.0.0",
  "cases": [
    {
      "id": "resolution.fallback.resolution-failure-stops",
      "requirementIds": ["LJ-RESOLUTION-014"],
      "fixture": "fallback-cardinality",
      "operation": "getResult",
      "input": {},
      "expected": {}
    }
  ]
}
~~~

- a nonempty `registrationBefore` frontier containing the activation milestone and every declared
  evidence-producer milestone, reduced only when the dependency DAG guarantees that another retained
  frontier milestone must start first;
